from fractions import Fraction as F
def gaps(s):
    return tuple(b - a for a, b in zip(s, s[1:]))
rule = gaps((F(11), F("16.5"), F(22)))
assert rule == gaps((F("14.5"), F(20), F("25.5"))) == (F("5.5"), F("5.5"))
opts = {"A": (14, "18.5", "23.5"), "B": ("21.5", 25, "31.5"), "C": ("24.5", 30, "36.5"), "D": (18, "23.5", 29)}
match = [k for k, v in opts.items() if gaps(tuple(F(str(x)) for x in v)) == rule]
assert len(match) == 1
print(f"ANSWER={match[0]}")

expr = ["P", "x", "S", "/", "M", "-", "T", "+", "R"]
gender, parent, spouse, sib = {}, {}, {}, {}
for a, op, b in zip(expr[0::2], expr[1::2], expr[2::2]):
    if op == "+": gender[a] = "m"; parent.setdefault(a, set()).add(b)
    if op == "/": gender[a] = "f"; parent.setdefault(a, set()).add(b)
    if op == "-": gender[a] = "f"; spouse[a] = b; spouse[b] = a
    if op == "x": gender[a] = "m"; sib[a] = b
for a, b in sib.items():
    parent[a] = set(parent.get(b, set()))
for c in list(parent):
    parent[c] |= {spouse[p] for p in parent[c] if p in spouse}
dad = [p for p in parent["P"] if p in parent and "R" in parent[p]]
assert len(dad) == 1 and gender[dad[0]] == "m" and gender["P"] == "m"
d = dad[0]
result = ("Son" if gender[d] == "m" else "Daughter") + "'s " + ("son" if gender["P"] == "m" else "daughter")
opts = {"A": "Daughter", "B": "Brother", "C": "Father's mother", "D": "Son's son"}

match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")

