from fractions import Fraction
expr = "12 + 12 - 4 * 4 / 2"
pairs = {"A": ("-", "+"), "B": ("+", "/"), "C": ("/", "-"), "D": ("*", "-")}
def swap(e, a, b):
    return "".join(b if ch == a else a if ch == b else ch for ch in e)
def ev(e):
    toks = e.split()
    return eval(" ".join(f"Fraction({t})" if t.isdigit() else t for t in toks))
match = [k for k, (a, b) in pairs.items() if ev(swap(expr, a, b)) == 22]
assert len(match) == 1
print(f"ANSWER={match[0]}")

